"""Normas posteriores a 2011 añadidas a la cronología (la recogida inicial cubre 1985-2011).
Cada «evidencia» se verifica contra el texto del BOE al generar el JSON (cronologia.py)."""

from comun import titulo


def n(doc, id_, rango, fecha, pub, resumen, cambios, modulos, estado, notas=None):
    d = {'id': id_, 'titulo': titulo(doc), 'rango': rango, 'fecha': fecha, 'fechaPublicacion': pub, 'boeId': doc,
         'confidence': 'alta', 'resumen': resumen, 'cambios': cambios, 'modulos': modulos, 'estado': estado}
    if notas:
        d['notas'] = notas
    return d


def c(parametro, antes, despues, transicion, articulos, evidencia):
    return {'parametro': parametro, 'antes': antes, 'despues': despues, 'transicion': transicion,
            'articulos': articulos, 'evidencia': evidencia}


